          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr><td class="px" style="padding:22px 40px 0px;"><div style="font-family:'IBM Plex Mono', ui-monospace, SFMono-Regular, 'Courier New', monospace; font-size:11px; font-weight:500; letter-spacing:0.16em; text-transform:uppercase; color:#4E7A66; margin:6px 0 14px;">Payment receipt</div><h1 class="h1 ink" style="margin:0 0 16px; font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:31px; font-weight:600; line-height:1.16; letter-spacing:-0.015em; color:#1F1B16;">Payment received.</h1><p class="ink2" style="margin:0 0 16px; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:16px; line-height:1.62; color:#4B463E;">Hi {{displayName}} — thank you. Here&#8217;s your receipt for order <strong style="color:#1F1B16; font-weight:600;">{{orderNumber}}</strong>.</p><table role="presentation" class="card" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%; background:#FFFFFF; border:1px solid #E6DDCC; border-radius:9px; margin:2px 0 20px;"><tr><td style="padding:22px 22px;"><div class="ink3" style="font-family:'IBM Plex Mono', ui-monospace, SFMono-Regular, 'Courier New', monospace; font-size:10px; font-weight:500; letter-spacing:0.12em; text-transform:uppercase; color:#8C8578; margin:0 0 3px;">Amount paid</div><div class="ink" style="font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:28px; font-weight:600; color:#1F1B16; margin:0;">{{amountFormatted}}</div><div class="hairbg" style="height:1px; background:#E6DDCC; font-size:0; line-height:0; margin:16px 0;">&nbsp;</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr><td style="padding:4px 0; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; color:#8C8578;" class="ink3">Paid on</td><td align="right" style="padding:4px 0; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; color:#1F1B16;" class="ink">{{paidAt}}</td></tr><tr><td style="padding:4px 0; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; color:#8C8578;" class="ink3">Card</td><td align="right" style="padding:4px 0; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; color:#1F1B16;" class="ink">{{cardBrand}} &#8226;&#8226;&#8226;&#8226; {{cardLast4}}</td></tr><tr><td style="padding:4px 0; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; color:#8C8578;" class="ink3">Transaction</td><td align="right" style="padding:4px 0; font-family:'IBM Plex Mono', ui-monospace, SFMono-Regular, 'Courier New', monospace; font-size:12px; color:#1F1B16;" class="ink">{{paymentIntentId}}</td></tr></table></td></tr></table><p class="ink3" style="margin:0; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:14px; line-height:1.6; color:#8C8578;">Keep this receipt for your records. Questions? Just reply to this email.</p><p class="ink2" style="margin:22px 0 0; font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:16px; font-style:italic; color:#4B463E;">— The Patina team</p></td></tr></table>
        </td></tr>
        <tr><td class="px" style="padding:34px 40px 0;">
          <div class="hairbg" style="height:1px; background:#E6DDCC; font-size:0; line-height:0;">&nbsp;</div>
        </td></tr>
        <tr><td class="px" style="padding:22px 40px 32px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr>
            <td align="left" valign="top">
              <div class="ink2" style="font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:15px; color:#4B463E; margin-bottom:5px;">Patina</div>
              <div class="ink3" style="font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; line-height:1.5; color:#8C8578;">A workshop for interior designers<br>and the makers they trust.</div>
            </td>
            <td align="right" valign="top" class="ink3" style="font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:13px; line-height:1.95; color:#8C8578;">
              <a href="{{dashboard_url}}" style="color:#4E7A66; text-decoration:none;">Dashboard</a><br>
              <a href="{{help_url}}" style="color:#4E7A66; text-decoration:none;">Help center</a><br>
              <a href="{{prefs_url}}" style="color:#4E7A66; text-decoration:none;">Email preferences</a>
            </td>
          </tr></table>
        </td></tr>
      </table>
      <!--[if mso]></td></tr></table><![endif]-->
      <table role="presentation" class="container" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px; max-width:600px;">
        <tr><td class="px" align="center" style="padding:18px 40px 10px; font-family:'IBM Plex Mono', ui-monospace, SFMono-Regular, 'Courier New', monospace; font-size:11px; line-height:1.8; letter-spacing:0.03em; color:#8C8578;">
          Patina &nbsp;·&nbsp; {{business_address}}<br>
          <a href="{{unsub_url}}" style="color:#8C8578; text-decoration:underline;">Unsubscribe</a> &nbsp;·&nbsp; <a href="{{prefs_url}}" style="color:#8C8578; text-decoration:underline;">Manage preferences</a>
