<body class="bg" style="margin:0; padding:0; background:#F5F0E6;">
  <div style="display:none; font-size:1px; line-height:1px; max-height:0; max-width:0; opacity:0; overflow:hidden; mso-hide:all; color:transparent;">Choose a new password for your Patina account. This link works for one hour.&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;</div>
  <table role="presentation" class="bg" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%; background:#F5F0E6;">
    <tr><td align="center" style="padding:24px 12px;">
      <!--[if mso]><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0"><tr><td><![endif]-->
      <table role="presentation" class="container shell" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px; max-width:600px; background:#FCF9F2; border:1px solid #E6DDCC; border-radius:12px; overflow:hidden;">
        <tr><td style="font-size:0; line-height:0; padding:0;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%; border-collapse:collapse;"><tr>
            <td width="33.34%" height="4" style="background:#4E7A66; height:4px; font-size:4px; line-height:4px; padding:0;">&nbsp;</td>
            <td width="33.33%" height="4" style="background:#B08A46; height:4px; font-size:4px; line-height:4px; padding:0;">&nbsp;</td>
            <td width="33.33%" height="4" style="background:#A24E2E; height:4px; font-size:4px; line-height:4px; padding:0;">&nbsp;</td>
          </tr></table>
