          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr>
            <td align="left" valign="middle" class="wordmark" style="font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:23px; font-weight:600; letter-spacing:-0.01em; color:#1F1B16;">Patina</td>
            <td align="right" valign="middle" class="ink3" style="font-family:'IBM Plex Mono', ui-monospace, SFMono-Regular, 'Courier New', monospace; font-size:11px; letter-spacing:0.14em; text-transform:uppercase; color:#8C8578;">Security</td>
          </tr></table>
        </td></tr>
        <tr><td style="padding:0;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;"><tr><td class="px" style="padding:22px 40px 0px;"><div style="font-family:'IBM Plex Mono', ui-monospace, SFMono-Regular, 'Courier New', monospace; font-size:11px; font-weight:500; letter-spacing:0.16em; text-transform:uppercase; color:#4E7A66; margin:6px 0 14px;">Password reset</div><h1 class="h1 ink" style="margin:0 0 16px; font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:31px; font-weight:600; line-height:1.16; letter-spacing:-0.015em; color:#1F1B16;">Reset your password.</h1><p class="ink2" style="margin:0 0 16px; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:16px; line-height:1.62; color:#4B463E;">Hi {{displayName}} — we got a request to reset your Patina password. Choose a new one below. For your security, this link works for the next hour.</p><div style="height:28px; line-height:28px; font-size:0;">&nbsp;</div><table role="presentation" class="btn" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#1F1B16" style="border-radius:7px;"><a href="{{resetUrl}}" style="display:inline-block; padding:15px 32px; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:15px; font-weight:600; line-height:1; letter-spacing:0.01em; background-color:#1F1B16; color:#F5F0E6; text-decoration:none; border:1px solid #1F1B16; border-radius:7px;">Reset password</a></td></tr></table><p class="ink3" style="margin:22px 0 0; font-family:'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; font-size:14px; line-height:1.6; color:#8C8578;">If you didn&#8217;t ask for this, you can ignore this email — your password stays exactly as it is.</p><p class="ink2" style="margin:22px 0 0; font-family:'Fraunces', Georgia, 'Times New Roman', serif; font-size:16px; font-style:italic; color:#4B463E;">— The Patina team</p></td></tr></table>
