$tmpl$,
   '[]'::jsonb, '["displayName","resetUrl","dashboard_url","help_url","prefs_url","unsub_url","business_address","app_url"]'::jsonb, true)
ON CONFLICT (slug) DO UPDATE SET
  name            = EXCLUDED.name,
  category        = EXCLUDED.category,
  subject_default = EXCLUDED.subject_default,
  html_content    = EXCLUDED.html_content,
  variables       = EXCLUDED.variables,
  is_active       = true,
  updated_at      = now();

-- ── The three 00336 arrival rows (hand-authored HTML, no bake path) ──────────
UPDATE public.email_templates AS t
SET html_content = s.h,
    updated_at   = now()
FROM (
  SELECT
    slug,
    replace(
    replace(
      replace(
        replace(
          replace(
            replace(
              html_content,
              $o$<tr><td style="font-size:0; line-height:0;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>$o$,
              $n$<tr><td style="font-size:0; line-height:0; padding:0;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%; border-collapse:collapse;"><tr>$n$
            ),
            $o$<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">$o$,
            $n$<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;">$n$
          ),
          $o$<table role="presentation" class="bg" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#F5F0E6;">$o$,
          $n$<table role="presentation" class="bg" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%; background:#F5F0E6;">$n$
        ),
        $o$height="4" style="background:#4E7A66; font-size:0; line-height:0;"$o$,
        $n$height="4" style="background:#4E7A66; height:4px; font-size:4px; line-height:4px; padding:0;"$n$
      ),
      $o$height="4" style="background:#B08A46; font-size:0; line-height:0;"$o$,
      $n$height="4" style="background:#B08A46; height:4px; font-size:4px; line-height:4px; padding:0;"$n$
    ),
    $o$height="4" style="background:#A24E2E; font-size:0; line-height:0;"$o$,
    $n$height="4" style="background:#A24E2E; height:4px; font-size:4px; line-height:4px; padding:0;"$n$
  ) AS h
  FROM public.email_templates
  WHERE slug IN ('design-request-held', 'design-request-intro-delivered', 'design-request-claimed')
) AS s
WHERE t.slug = s.slug
  AND t.html_content IS DISTINCT FROM s.h;
